// Takes whatever your contact form posts and makes it predictable.
// Expected fields: name, email, phone, message, source. All optional —
// the flow decides for itself whether there is enough to work with.

const b = $input.first().json.body || {};
const clean = s => String(s || '').trim();

const name    = clean(b.name);
const email   = clean(b.email);
const phone   = clean(b.phone).replace(/[^0-9+]/g, '');
const message = clean(b.message);
const source  = clean(b.source) || 'website form';

// A name, a message, and at least one way to reply. Plenty of forms do not
// ask for an email — somebody who leaves only a phone number is a customer,
// not spam, so either one is enough.
const emailOk = /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email);
const phoneOk = phone.replace(/\D/g, '').length >= 7;

const problems = [];
if (!name) problems.push('no name');
if (!emailOk && !phoneOk) problems.push('no email and no phone — nowhere to reply');
if (!message) problems.push('empty message');

return [{ json: {
  name,
  email: emailOk ? email : '',
  phone: phoneOk ? phone : '',
  message,
  source,
  valid: problems.length === 0,
  problems,
  received_at: new Date().toISOString()
} }];

// ─────────────────────────────────────────────────────────────────────
//  EDIT THIS BLOCK — it is the whole of the tuning.
//  The example is a plumber. Swap the words for your own trade and the
//  rest of the workflow needs no changes.
// ─────────────────────────────────────────────────────────────────────
const RULES = [
  { intent: 'junk',      score: 0,  words: ['seo', 'backlink', 'guest post', 'we offer', 'our agency',
                                            'increase your traffic', 'digital marketing', 'lead generation service'] },
  { intent: 'emergency', score: 45, words: ['burst', 'flood', 'leak', 'leaking', 'no hot water', 'no heating',
                                            'gas leak', 'smell of gas', 'blocked', 'overflowing', 'urgent',
                                            'emergency', 'asap', 'tonight', 'today', 'straight away'] },
  { intent: 'quote',     score: 30, words: ['quote', 'estimate', 'price', 'how much', 'cost', 'budget'] },
  { intent: 'booking',   score: 30, words: ['book', 'appointment', 'schedule', 'availability', 'slot',
                                            'come round', 'come out', 'when can you'] },
  { intent: 'service',   score: 20, words: ['service', 'annual', 'certificate', 'landlord', 'inspection',
                                            'maintenance'] }
];

// "not urgent" must beat the word "urgent" sitting next to it
const NOT_URGENT = ['not urgent', 'no rush', 'no hurry', 'whenever', 'just asking', 'just wondering'];

const BONUS      = { has_phone: 15, long_message: 10, company: 10, out_of_hours: 10 };
const THRESHOLDS = { hot: 45, warm: 25 };
const OPEN       = { start: 8, end: 18, days: [1, 2, 3, 4, 5] };   // 8am–6pm, Mon–Fri

// What you need before you can give a straight answer, per intent
const NEEDED = {
  emergency: ['address'],
  quote:     ['address', 'preferred date'],
  booking:   ['address', 'preferred date'],
  service:   ['address', 'preferred date']
};
// ───────────────────────── end of the editable block ─────────────────

const d = $input.first().json;
const text = ((d.message || '') + ' ' + (d.source || '')).toLowerCase();

const now = new Date();
const openNow = OPEN.days.includes(now.getDay())
             && now.getHours() >= OPEN.start && now.getHours() < OPEN.end;

// Sales pitches are checked FIRST. Otherwise "we offer SEO services" matches
// the word "service" and reaches the owner as a real enquiry.
const junk = RULES.find(r => r.intent === 'junk');
if (junk && junk.words.some(w => text.includes(w))) {
  return [{ json: { ...d, intent: 'junk', score: 0, tier: 'cold', missing: [], open_now: openNow } }];
}

let intent = 'general enquiry';
let score  = 10;
for (const r of RULES) {
  if (r.intent === 'junk') continue;
  if (r.words.some(w => text.includes(w))) { intent = r.intent; score = r.score; break; }
}

if (NOT_URGENT.some(w => text.includes(w)) && intent === 'emergency') {
  intent = 'general enquiry';
  score  = 15;
}

if (d.phone) score += BONUS.has_phone;
if ((d.message || '').length > 80) score += BONUS.long_message;
if (/\b(ltd|limited|gmbh|srl|inc|company|business)\b/i.test(text)) score += BONUS.company;
if (!openNow) score += BONUS.out_of_hours;

const tier = score >= THRESHOLDS.hot ? 'hot' : score >= THRESHOLDS.warm ? 'warm' : 'cold';

// What is missing — this is what turns a reply into a second question
const missing = [];
if (!d.phone) missing.push('phone number');
if (!d.email) missing.push('email address');
for (const need of (NEEDED[intent] || ['address'])) {
  if (need === 'address' && !/\b(address|street|road|lane|avenue|city|postcode|zip)\b/i.test(text)) {
    missing.push('address');
  }
  if (need === 'preferred date' && !/\b(today|tomorrow|monday|tuesday|wednesday|thursday|friday|saturday|sunday|next week|morning|afternoon|evening)\b/i.test(text)) {
    missing.push('preferred date');
  }
}

return [{ json: { ...d, intent, score, tier, missing, open_now: openNow } }];

// ── your business, in one place ──────────────────────────────────────
const BUSINESS = 'our team';          // e.g. 'Bridge Street Heating'
const PHONE    = '';                  // leave empty and no phone line is offered
// ─────────────────────────────────────────────────────────────────────

const d = $input.first().json;
const first = (d.name || '').split(' ')[0] || 'there';

// What the visitor sees, on the page, straight away
let reply;
if (!d.valid) {
  reply = `${d.name ? 'Thanks ' + first + '.' : 'Thanks.'} We could not quite read that — could you send it again with a phone number or an email so we can come back to you?`;
} else if (d.intent === 'junk') {
  reply = 'Thanks for getting in touch.';
} else {
  const urgent = d.intent === 'emergency' ? ' and we are treating it as urgent' : '';
  const ask = d.missing.length
    ? `\n\nTo give you a straight answer quickly, could you send us your ${d.missing.join(' and ')}? You can reply right here.`
    : '';
  const closed = d.open_now ? '' : '\n\nWe are closed right now, but this has gone straight through to us.';
  const call = PHONE ? `\n\nIf it cannot wait, call us on ${PHONE}.` : '';
  reply = `Hi ${first}, we have got your message${urgent}.${ask}${closed}${call}`;
}

// What the owner gets on his phone
const icon = d.tier === 'hot' ? '🔥' : d.tier === 'warm' ? '🟡' : '⚪';
const alert = [
  `${icon} ${String(d.tier).toUpperCase()} LEAD (${d.score}) — ${d.intent}`,
  '',
  d.name,
  [d.email, d.phone].filter(Boolean).join(' · '),
  `Source: ${d.source}`,
  d.open_now ? '' : '⏰ Came in outside working hours.',
  '',
  `"${d.message}"`,
  d.missing.length ? `\nMissing: ${d.missing.join(', ')}` : ''
].filter(l => l !== '').join('\n');

// Junk is answered politely and never buzzes anybody
const tell_owner = d.valid && d.intent !== 'junk';

return [{ json: { ...d, reply_to_customer: reply, alert_to_owner: alert, tell_owner } }];
